UPDATE TB_TRMA_TOUR_LIST
TOUR_NM_EN = #{tourNmEn}, TOUR_NM_JA = #{tourNmJa}, TOUR_CONTENT_EN = #{overviewEn}, TOUR_CONTENT_JA = #{overviewJa}, ROAD_ADDR_EN = #{roadAddrEn}, ROAD_ADDR_JA = #{roadAddrJa}, DETAIL_ADDR_EN = #{detailAddrEn}, DETAIL_ADDR_JA = #{detailAddrJa},
WHERE TOUR_ID = #{tourId}

UPDATE TB_TRMA_MOIM_REVIEW
REVIEW_TITLE_EN = #{reviewTitleEn}, REVIEW_TITLE_JA = #{reviewTitleJa}, REVIEW_CONTENT_EN = #{reviewContentEn}, REVIEW_CONTENT_JA = #{reviewContentJa},
WHERE REVIEW_ID = #{reviewId}

mapper.insert:
INSERT INTO TB_TRMA_TOUR_AI_INFO
(
    TOUR_ID
    ,LANG_CD
    ,OPERATING_HOURS
    ,CLOSED_DAYS
    ,ADMISSION_FEE_IS_FREE
    ,ADMISSION_FEE_DETAILS
    ,WEBSITE_URL
    ,PARKING_AVAILABLE
    ,PARKING_FEE_INFO
    ,LAST_UPDATED_NOTE
    ,UPDATE_DT
)VALUES(
    #{tourId}
    ,#{langCd}
    ,#{data.operatingHours}
    ,#{data.closedDays}
    ,#{data.admissionFeeIsFree}
    ,#{data.admissionFeeDetails}
    ,#{data.websiteUrl}
    ,#{data.parkingAvailable}
    ,#{data.parkingFeeInfo}
    ,#{data.lastUpdatedNote}
    ,CURRENT_TIMESTAMP
)
ON DUPLICATE KEY UPDATE
    OPERATING_HOURS = #{data.operatingHours}
    ,CLOSED_DAYS = #{data.closedDays}
    ,ADMISSION_FEE_IS_FREE = #{data.admissionFeeIsFree}
    ,ADMISSION_FEE_DETAILS = #{data.admissionFeeDetails}
    ,WEBSITE_URL = #{data.websiteUrl}
    ,PARKING_AVAILABLE = #{data.parkingAvailable}
    ,PARKING_FEE_INFO = #{data.parkingFeeInfo}
    ,LAST_UPDATED_NOTE = #{data.lastUpdatedNote}
    ,UPDATE_DT = CURRENT_TIMESTAMP
